// Holds the full normalised card queue per active session.
// Cleared after 4 h (well beyond any realistic session length).
const _sessionQueues = new Map(); // sessionId â†’ normalizedCards[]
const PAGE_SIZE = 20;

// â”€â”€ WebSocket client registry â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const _wsClients = new Map(); // userId (string) â†’ Set<WebSocket>
function wsSend(userId, event, data) {
  const clients = _wsClients.get(String(userId));
  if (!clients) return;
  const msg = JSON.stringify({ event, data, ts: Date.now() });
  for (const ws of clients) {
    try { if (ws.readyState === 1) ws.send(msg); } catch (_) {}
  }
}

// â”€â”€ In-memory job store â€” enables GET /api/jobs/:id polling fallback (Bug 2 fix) â”€â”€
// Jobs are ephemeral (WS-first); this store is the safety net when WS is slow/down.
// TTL: 10 min per entry. Cleaned up lazily on each write.
const _jobStore = new Map(); // jobId â†’ { status, type, result?, error?, expiresAt }
function _jobStoreSet(jobId, data) {
  const expiresAt = Date.now() + 600_000; // 10-minute TTL
  _jobStore.set(jobId, { ...data, expiresAt });
  // Lazy cleanup of expired entries
  for (const [k, v] of _jobStore) {
    if (v.expiresAt < Date.now()) _jobStore.delete(k);
  }
  // ROOT FIX: Persist to PostgreSQL so polls survive server restarts / multi-instance deployments.
  // In-memory _jobStore is the fast path; DB is the durable fallback.
  query(
    `INSERT INTO background_jobs (id, status, type, result, error, expires_at)
     VALUES ($1, $2, $3, $4::jsonb, $5, NOW() + INTERVAL '10 minutes')
     ON CONFLICT (id) DO UPDATE SET
       status     = EXCLUDED.status,
       result     = EXCLUDED.result,
       error      = EXCLUDED.error,
       expires_at = EXCLUDED.expires_at`,
    [jobId, data.status, data.type,
     data.result ? JSON.stringify(data.result) : null,
     data.error || null]
  ).catch(() => {}); // fire-and-forget â€” never block the caller
}

